// Maps each normalized email to its position in `result`, so lookups do not rescan the list.
// The first occurrence wins, matching the previous linear search.
const indexByEmail = new Map<string, number>();
result.forEach((entry, index) => {
  const key = normalizeEmail(entry.email);
  if (!indexByEmail.has(key)) indexByEmail.set(key, index);
});
for (const contact of incoming) {
  const key = normalizeEmail(contact.email);
  const index = indexByEmail.get(key);
  if (index === undefined) {
    indexByEmail.set(key, result.length);
    result.push(contact);
  } else {
    result[index] = mergeContact(result[index], contact);
  }
}
return result;

